package com.antigravity.mobile.ui.util

import java.util.Locale
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

/**
 * 全局统一本地化引擎，支持中文 / 英文 / 日语并跟随系统语言。
 * 规则：zh* -> 简体中文；ja* -> 日语；其余所有语言 -> 英文。
 */
object L10n {
    enum class AppLang { ZH, EN, JA }

    @Volatile
    private var languagePref: String = "system"

    private val _currentLangFlow = MutableStateFlow("system")
    val currentLangFlow: StateFlow<String> = _currentLangFlow.asStateFlow()

    fun setLanguagePreference(pref: String) {
        languagePref = pref
        _currentLangFlow.value = pref
    }

    fun getLanguagePreference(): String = languagePref

    val currentLang: AppLang
        get() = when (languagePref) {
            "en" -> AppLang.EN
            "ja" -> AppLang.JA
            "zh" -> AppLang.ZH
            else -> {
                val lang = Locale.getDefault().language.lowercase()
                when {
                    lang.startsWith("zh") -> AppLang.ZH
                    lang.startsWith("ja") -> AppLang.JA
                    else -> AppLang.EN
                }
            }
        }

    val isEnglish: Boolean
        get() = currentLang == AppLang.EN

    val isJapanese: Boolean
        get() = currentLang == AppLang.JA

    val isChinese: Boolean
        get() = currentLang == AppLang.ZH

    private data class PatternRule(
        val regex: Regex,
        val transform: (MatchResult) -> String
    )

    private fun enPlural(n: String, singular: String, plural: String): String =
        if (n == "1") "$n $singular" else "$n $plural"

