    private val dictEn: Map<String, String> by lazy {
        val map = HashMap<String, String>(2300)
        populateEnChunk0(map)
        populateEnChunk1(map)
        populateEnChunk2(map)
        populateEnChunk3(map)
        populateEnChunk4(map)
        populateEnChunk5(map)
        populateEnChunk6(map)
        populateEnChunk7(map)
        map
    }

    private val dictJa: Map<String, String> by lazy {
        val map = HashMap<String, String>(2300)
        populateJaChunk0(map)
        populateJaChunk1(map)
        populateJaChunk2(map)
        populateJaChunk3(map)
        populateJaChunk4(map)
        populateJaChunk5(map)
        populateJaChunk6(map)
        populateJaChunk7(map)
        map
    }

    fun t(chinese: String): String {
        val lang = currentLang
        if (lang == AppLang.ZH || chinese.isEmpty()) return chinese

        val activeDict = if (lang == AppLang.JA) dictJa else dictEn
        val activeRules = if (lang == AppLang.JA) patternRulesJa else patternRulesEn

        // 1. 精确匹配
        val exact = activeDict[chinese]
        if (exact != null) return exact

        // 2. 正则模式匹配
        for (rule in activeRules) {
            val m = rule.regex.matchEntire(chinese)
            if (m != null) {
                return rule.transform(m)
            }
        }

        return chinese
    }

    fun format(chinese: String, vararg args: Any): String {
        val translated = t(chinese)
        return if (args.isNotEmpty()) {
            val fmtLocale = when (currentLang) {
                AppLang.ZH -> Locale.SIMPLIFIED_CHINESE
                AppLang.JA -> Locale.JAPANESE
                AppLang.EN -> Locale.US
            }
            try {
                String.format(fmtLocale, translated, *args)
            } catch (_: Exception) {
                translated
            }
        } else {
            translated
        }
    }

