/** 扩展属性：返回跟随系统语言的本地化文本。 */
val String.loc: String
    get() = L10n.t(this)

/** 扩展函数：带格式化参数的本地化文本。 */
fun String.loc(vararg args: Any): String = L10n.format(this, *args)
